using Microsoft.Data.Sqlite;
using MiniPharmacie.Business.Models;
using MiniPharmacie.Business.Services;
using MiniPharmacie.Data.Database;

namespace MiniPharmacie.Tests;

public sealed class StockWorkflowTests
{
    private static async Task<(DatabaseInitializer Db,StockManagementService Stock,long User,long Product,long Supplier)> Setup(){var db=new DatabaseInitializer(Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".db"));await db.InitializeAsync();await using var c=db.CreateConnection();await c.OpenAsync();await using var q=c.CreateCommand();q.CommandText="INSERT INTO Roles(Name) VALUES('Responsable');INSERT INTO Users(RoleId,Username,PasswordHash,CreatedAt) VALUES(1,'test','hash',datetime('now'));INSERT INTO Categories(Name) VALUES('Médicaments');INSERT INTO Products(CategoryId,Code,Name,Unit,SalePriceMinor,ReorderLevel) VALUES(1,'P-01','Produit test','boîte',500,5);INSERT INTO Suppliers(Name) VALUES('Fournisseur test');";await q.ExecuteNonQueryAsync();return(db,new StockManagementService(db),1,1,1);}
    [Fact] public async Task DuplicateProductReferenceIsRejected(){var (db,s,u,p,v)=await Setup();await Assert.ThrowsAsync<InvalidOperationException>(()=>s.SaveProductAsync(new("P-01","Doublon",null,"","","boîte",1,0,null,null),u));}
    [Fact] public async Task ReceiptAddsStockOnlyAfterCommitAndSaleConsumesFefo(){var (db,s,u,p,v)=await Setup();var receipt=await s.ReceiveAsync(new(v,u,"R-001",DateTimeOffset.Now,[new(p,20,200,"LOT-1",DateOnly.FromDateTime(DateTime.Today.AddDays(200)))],null));Assert.True(receipt>0);Assert.Equal(20,(await s.GetProductsAsync()).Single().Physical);await s.SellAsync(p,3,u);Assert.Equal(17,(await s.GetProductsAsync()).Single().Physical);}
    [Fact] public async Task ExpiredAndBlockedLotsAreNotSellable(){var(db,s,u,p,v)=await Setup();await s.ReceiveAsync(new(v,u,"R-1",DateTimeOffset.Now,[new(p,5,200,"EXPIRE",DateOnly.FromDateTime(DateTime.Today.AddDays(-1)))],null));await s.ReceiveAsync(new(v,u,"R-2",DateTimeOffset.Now,[new(p,4,200,"BLOCK",DateOnly.FromDateTime(DateTime.Today.AddDays(200)))],null));await using var c=db.CreateConnection();await c.OpenAsync();await using var q=c.CreateCommand();q.CommandText="UPDATE Lots SET IsBlocked=1 WHERE LotNumber='BLOCK'";await q.ExecuteNonQueryAsync();Assert.Equal(0,(await s.GetProductsAsync()).Single().Sellable);}
    [Fact] public async Task AdjustmentWithoutReasonIsRejected(){var(db,s,u,p,v)=await Setup();await s.ReceiveAsync(new(v,u,"R-1",DateTimeOffset.Now,[new(p,5,200,"LOT-1",null)],null));await using var c=db.CreateConnection();await c.OpenAsync();await using var q=c.CreateCommand();q.CommandText="SELECT Id FROM Lots LIMIT 1";var lot=(long)(await q.ExecuteScalarAsync())!;await Assert.ThrowsAsync<ArgumentException>(()=>s.AdjustLotAsync(lot,2,u," "));}
    [Fact] public async Task ProductWithStockHistoryIsArchived(){var(db,s,u,p,v)=await Setup();await s.ReceiveAsync(new(v,u,"R-1",DateTimeOffset.Now,[new(p,5,200,"LOT-1",null)],null));await s.ArchiveOrDeleteProductAsync(p,u);await using var c=db.CreateConnection();await c.OpenAsync();await using var q=c.CreateCommand();q.CommandText="SELECT IsActive FROM Products WHERE Id=$id";q.Parameters.AddWithValue("$id",p);Assert.Equal(0L,(long)(await q.ExecuteScalarAsync())!);}
    [Fact] public async Task InvalidReceiptRollsBackAllRows(){var(db,s,u,p,v)=await Setup();await Assert.ThrowsAnyAsync<Exception>(()=>s.ReceiveAsync(new(v,u,"R-BAD",DateTimeOffset.Now,[new(p,7,200,"LOT-1",null),new(999,3,100,"LOT-2",null)],null)));await using var c=db.CreateConnection();await c.OpenAsync();await using var q=c.CreateCommand();q.CommandText="SELECT (SELECT COUNT(*) FROM Receipts)+(SELECT COUNT(*) FROM Lots)+(SELECT COUNT(*) FROM StockMovements)";Assert.Equal(0L,(long)(await q.ExecuteScalarAsync())!);}
}
